          "source_scope": "record_text"
        },
        {
          "doc_id": "I5FSG7WPPXXIFW4",
          "support_span": "Page 7, Line 12, discloses monitoring signal parameter of all neighbor cells at relatively high rate",
          "source_scope": "record_text"
        },
        {
          "doc_id": "I5FSG7WPPXXIFW4",
          "support_span": "Page 7, Lines 14-17, discloses monitoring signal parameter of all neighbor cells at relatively low rate",
          "source_scope": "record_text"
        }
      ],
      "evidence_status": "record_supported"
