        },
        {
          "doc_id": "HNQ6UMIGPXXIFW4",
          "support_span": "Kato discloses ... wherein the excitation light is a single wavelength laser beam in the ultraviolet spectrum",
          "source_scope": "record_text"
        },
        {
          "doc_id": "HNQ6UMIGPXXIFW4",
          "support_span": "Kajino discloses, in Fig. 23, an illuminator ... collimating lenses 402 ... dichroic prism 403 ... scan mirror section 406 receiving the red, green, and blue light beams from dichroic prism 403 and scans said beams together to form an image on screen 420",
          "source_scope": "record_text"
        }
      ],
      "evidence_status": "record_supported"
    },
    {
      "claim_ids": [
        2
      ],
      "ground": "103",
      "claim_version_doc_ids": [
        "HRII4MC4PXXIFW3"
      ],
      "status": "maintained",
      "rationale": "Claim 2 (as amended to recite a fourth collimator between the laser module and fluorescent members) is prima facie obvious over the same combination plus Kurosaki, which discloses collimator lenses disposed between a laser module and a fluorescent wheel to collimate the excitation beam.",
      "evidence": [
        {
          "doc_id": "HNQ6UMIGPXXIFW4",
          "support_span": "Claim 2 is rejected under pre-AIA 35 U.S.C. 103(a) ... and further in view of Kurosaki.",
          "source_scope": "record_text"
        },
        {
