        5,
        6
      ],
      "ground": "112b",
      "claim_version_doc_ids": [
        "HNQ6UMIGPXXIFW4",
        "HRII4MC4PXXIFW3"
      ],
      "status": "withdrawn",
      "rationale": "Applicant amended claims 1 and 3 and canceled claims 4-6 in response to the 35 U.S.C. 112(b) objections. The prior 112(b) rejection as to the dismissed/cancelled claims is moot for those canceled claims. For the pending amended claims 1 and 3, the examiner finds the amendment addresses the earlier indefiniteness by replacing ambiguous 'lens' terminology with 'scanning optical system' and specifically reciting 'first/second/third dichroic mirror' language; therefore the 112(b) rejection is withdrawn as to claims 1 and 3.",
      "evidence": [
        {
          "doc_id": "HNQ6UMIGPXXIFW4",
          "support_span": "Claims 1 and 3-6 are rejected under 35 U.S.C. 112(b) ... as being indefinite",
          "source_scope": "record_text"
        },
        {
          "doc_id": "HRII4MC4PXXIFW3",
          "support_span": "a scanning optical system ... a first dichroic mirror ... a second dichroic mirror ... a third dichroic mirror",
          "source_scope": "record_text"
        }
      ],
      "evidence_status": "record_supported"
    }
