        {
          "doc_id": "IPPLGGCBRXEAPX1",
          "support_span": "Claims 1-16, 18, 19, as best understood, are rejected under 35 U.S.C. 103 as being unpatentable over Spruce et al. (US 2013/0106107 A1) in view of Kusiak et al.",
          "source_scope": "record_text"
        },
